# Creates the commands listed in data/operations.json (generated by build/apigen from the
# official TOPdesk API specifications). Each command is a thin function that calls
# Invoke-TdOperation, so the table holds the API knowledge and the code exists only once.

$operationsPath = Join-Path (Join-Path $script:ModuleRoot 'data') 'operations.json'
$script:TdOperations = @{}
$operationScripts = foreach ($command in (ConvertFrom-TdJson -Json ([System.IO.File]::ReadAllText($operationsPath, [System.Text.Encoding]::UTF8)))) {
    $script:TdOperations[$command.name] = $command
    ConvertTo-TdOperationScript -Command $command
}
. ([scriptblock]::Create(($operationScripts -join "`n`n")))
Remove-Variable -Name operationsPath, operationScripts, command -ErrorAction Ignore
